	while true do
for _, player in pairs(Players:GetPlayers()) do
	if TargetLookup[player.Name] then
createTag(player)
	end
end
task.wait(CHECK_INTERVAL)
	end
end)

Players.PlayerAdded:Connect(function(player)
	if TargetLookup[player.Name] then
player.CharacterAdded:Connect(function()
	task.wait(1)
	createTag(player)
end)
end
end)
end)











