	if not m.AddFunctions then
		if m._factory then pcall(GiveFunctionsToModule, m._factory) end
		local hash = GetModuleHash(m)
		if TDZConfigs[hash] and m.LoadConfig then
			pcall(m.LoadConfig, TDZConfigs[hash])
