	Stroke.Thickness= 1
	Stroke.Color= Color3.fromRGB(180, 0, 0)

	local bindable = Instance.new("BindableEvent")
	local proxy= { Changed = bindable.Event }
	box.FocusLost:Connect(function()
		bindable:Fire(box.Text)
	end)
	return proxy
end

