z="Z",x="X",c="C",v="V",b="B",n="N",comma=",",leftbracket="[",rightbracket="]",minus="-"
}

local KEYS_PER_PAGE = #KEY_ORDER  -- 26 per Page

for _, dance in ipairs(TableOfDances) do
